        elif self.article is not None and tag == "span" and "contributor" in attributes.get("class", "").split():
            self.contributor_depth = self.depth
            self.contributor_parts = []

    def handle_data(self, data):
        if self.title_depth is not None:
            self.title_parts.append(data)
        if self.contributor_depth is not None:
            self.contributor_parts.append(data)

    def handle_endtag(self, tag):
        if self.contributor_depth == self.depth and tag == "span":
            text = " ".join("".join(self.contributor_parts).split())
            if text:
                self.contributors.append(text)
            self.contributor_depth = None
