            self.title_depth = None
            self.contributor_depth = None
        self.depth -= 1

    def parse(self, text):
        self.records = []
        self.feed(text)
        self.close()
        if self.article is not None:
            raise ValueError("unclosed article")
        return self.records


def collect_entries(pages):
    seen = set()
    result = []
    for page in pages:
        if not isinstance(page, str):
            raise ValueError("every page must be a string")
        parser = _CatalogueParser()
        for rank_text, score_text, title, contributors in parser.parse(page):
            try:
                if not rank_text or not rank_text.isascii() or not rank_text.isdecimal():
                    continue
                rank = int(rank_text)
                score = float(score_text)
            except (TypeError, ValueError):
                continue
            if rank <= 0 or not math.isfinite(score) or not title or rank in seen:
                continue
            seen.add(rank)
            result.append({"rank": rank, "title": title, "contributors": list(contributors), "score": score})
    result.sort(key=lambda item: item["score"])
    return result

