import unittest

from solution import collect_entries


class OneShotPages:
    def __init__(self, values):
        self.values = values
        self.used = False

    def __iter__(self):
        if self.used:
            raise AssertionError("pages iterable consumed more than once")
        self.used = True
        return iter(self.values)


class CollectEntriesTests(unittest.TestCase):
    def test_extracts_nested_visible_text_and_sorts(self):
        pages = OneShotPages([
            '<article data-score="8.5" data-rank="2"><div><h2> Second <em>Title</em> </h2></div><span class="contributor"> Ann </span><span class="x contributor y"><b>Bob</b></span></article>',
            '<article id="a" data-rank="1" data-score="9"><h2> First &amp; Best </h2><span class="contributor">  </span></article>',
        ])
        self.assertEqual(collect_entries(pages), [
            {"rank": 1, "title": "First & Best", "contributors": [], "score": 9.0},
            {"rank": 2, "title": "Second Title", "contributors": ["Ann", "Bob"], "score": 8.5},
        ])

    def test_skips_invalid_articles_and_keeps_first_valid_duplicate(self):
        html = (
            '<article data-rank="0" data-score="1"><h2>Zero</h2></article>'
            '<article data-rank="3" data-score="nan"><h2>NaN</h2></article>'
            '<article data-rank="4" data-score="2"></article>'
            '<article data-rank="5" data-score="2"><h2>   </h2></article>'
            '<article data-rank="2" data-score="1.25"><h2>Kept</h2></article>'
            '<article data-rank="2" data-score="9"><h2>Ignored</h2></article>'
        )
        self.assertEqual(collect_entries([html]), [
            {"rank": 2, "title": "Kept", "contributors": [], "score": 1.25}
        ])

    def test_empty_input_and_fresh_allocations(self):
        self.assertEqual(collect_entries([]), [])
        html = '<article data-rank="1" data-score="2"><h2>A</h2><span class="contributor">C</span></article>'
        first = collect_entries([html])
        second = collect_entries([html])
        first[0]["title"] = "changed"
        first[0]["contributors"].append("X")
        self.assertEqual(second, [{"rank": 1, "title": "A", "contributors": ["C"], "score": 2.0}])
        self.assertIsNot(first[0], second[0])
        self.assertIsNot(first[0]["contributors"], second[0]["contributors"])

    def test_non_string_page_and_unclosed_article_raise(self):
        with self.assertRaises(ValueError):
            collect_entries(["<p>ok</p>", 3])
        with self.assertRaises(ValueError):
            collect_entries(['<article data-rank="1" data-score="2"><h2>Open</h2>'])


if __name__ == "__main__":
    unittest.main()

